# variables.tf -- replace the source_ranges validation block:
  validation {
    condition     = length(var.source_ranges) > 0 && !contains(var.source_ranges, "0.0.0.0/0") && !contains(var.source_ranges, "::/0")
    error_message = "source_ranges must contain at least one CIDR range and must not include 0.0.0.0/0 or ::/0 -- this module builds an internal-only load balancer; unrestricted source ranges defeat that guarantee."
  }

# variables.tf -- replace the allow validation block:
  validation {
    condition     = length(var.allow) > 0 && alltrue([for a in var.allow : lower(a.protocol) != "all"])
    error_message = "allow must contain at least one protocol/port entry and must not use protocol \"all\" -- this module builds an internal-only load balancer; specify explicit protocols/ports."
  }
